    // [WSCoop] Luminary respec (see WSLuminaryRespec). Spent points are derived from GrantedUnlocks, so
    // dropping an entry refunds its point.
    bool WSRemoveUnlock(const UProgressionUnlockDefinition Unlock)
    {
        if (!System::IsServer() || Unlock == nullptr)
            return false;
        for (int Idx = GrantedUnlocks.Num() - 1; Idx >= 0; --Idx)
        {
            if (GrantedUnlocks[Idx] != Unlock)
                continue;
            GrantedUnlocks.RemoveAt(Idx);
            WSRebuildRecipes();
            return true;
        }
        return false;
    }

    TArray<const UProgressionUnlockDefinition> WSGetGrantedUnlocks() const
    {
        return GrantedUnlocks;
    }

    int WSCountGranted(const UProgressionUnlockDefinition Unlock) const
    {
        int Count = 0;
        for (const UProgressionUnlockDefinition Granted : GrantedUnlocks)
        {
            if (Granted == Unlock)
                Count++;
        }
        return Count;
    }

    void WSRebuildRecipes()
    {
        GrantedRecipes.Empty();
        for (const UProgressionUnlockDefinition Granted : GrantedUnlocks)
        {
            if (Granted != nullptr)
                GrantedRecipes.Append(Granted.GetRecipes());
        }
    }

    // Server, after a respec: refresh every game's menus. Clients take the new list from replication, so they
    // refresh now and again shortly after (the replicated state may arrive after this call).
    UFUNCTION(NetMulticast)
    void WSClientRespecDone()
    {
        WSClientRefresh();
        if (!System::IsServer())
            System::SetTimer(this, n"WSClientRefreshLater", 0.3, false);
    }

    UFUNCTION()
    private void WSClientRefreshLater()
    {
        WSClientRefresh();
        System::SetTimer(this, n"WSClientRefresh", 0.7, false);
    }

    // An unlock-granted event without an unlock (and flagged as loading, so quests ignore it) = "redraw".
    UFUNCTION()
    void WSClientRefresh()
    {
        if (!System::IsServer())
            WSRebuildRecipes();
        OnUnlockGranted.Broadcast(nullptr, FProgressionUnlockInstanceData(), true);
    }
